const CATS = ['All','Mathematics','Astronomy','Life Sciences','Metallurgy','Architecture','Philosophy','Linguistics & CS','Agriculture','Water Engineering'];

function usePersistedState(key, fallback) {
  const [value, setValue] = useState(() => localStorage.getItem(key) ?? fallback);
  const update = next => {
    const resolved = typeof next === 'function' ? next(value) : next;
    localStorage.setItem(key, String(resolved));
    setValue(resolved);
  };
  return [value, update];
}

function localUser(name = 'Guest Learner') {
  const id = `local_${Date.now().toString(36)}`;
  return { id, name, email: `${id}@local.iksphere`, role:'learner', provider:'local', is_guest:1 };
}

function LoginScreen({ onLogged, language, setLanguage, onRequestedRole }) {
  const [mode, setMode] = useState('google');
  const [accountType, setAccountType] = useState('learner');
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [create, setCreate] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [localOnly, setLocalOnly] = useState(false);

  const finishFirebase = async (cred, provider) => {
    const firebaseUser = cred.user;
    const token = await firebaseUser.getIdToken();
    const user = await api.authFirebase({
      id_token: token,
      name: firebaseUser.displayName || name || 'IKSphere Learner',
      email: firebaseUser.email || '',
      provider,
    });
    if(accountType==='teacher'&&user.role!=='teacher'){await firebaseLogout();throw new Error(t('This email is not approved for teacher access. Add it to the server TEACHER_EMAILS list.',language))}
    setApiSession({token, userId:user.id});
    onLogged(user, token);
  };

  const handleGoogle = async () => {
    setError(''); setBusy(true);
    try {
      const cred = await loginWithGoogle();
      if (cred) await finishFirebase(cred, 'google');
    } catch (e) { setError(e?.message || t('Google sign-in failed.',language)); }
    finally { setBusy(false); }
  };

  const handleEmail = async () => {
    if (!email.trim() || password.length < 6 || (create && name.trim().length < 2)) return setError(t('Enter a valid name, email and a password of at least 6 characters.',language));
    setError(''); setBusy(true);
    try {
      const cred = create ? await createEmailAccount(name, email, password) : await loginWithEmail(email, password);
      await finishFirebase(cred, 'password');
    } catch (e) { setError(e?.message?.replace('Firebase: Error (auth/', '').replace(').','') || t('Email sign-in failed.',language)); }
    finally { setBusy(false); }
  };

  const handleGuest = async () => {
    setError(''); setBusy(true);
    try {
      if (firebaseConfigured) {
        const cred = await loginAsGuest();
        const token = await cred.user.getIdToken();
        const user = await api.authFirebase({id_token:token,name:name.trim() || 'Guest Learner',email:'',provider:'anonymous'});
        setApiSession({token,userId:user.id});
        onLogged(user, token);
      } else {
        const user = await api.authGuest(name.trim() || 'Guest Learner');
        setApiSession({userId:user.id});
        onLogged(user, '');
      }
    } catch (e) { setError(e?.message || t('Guest sign-in failed.',language)); }
    finally { setBusy(false); }
  };

  const handleLocalDemo = async (teacher=false) => {
    setError(''); setBusy(true);
    try {
      const user = await api.authLocal({name:teacher?'Teacher Demo':'Learner Demo',email:teacher?'teacher@iksphere.local':'student@iksphere.local',role:teacher?'teacher':'learner'});
      clearApiSession(); setApiSession({userId:user.id}); onLogged(user, '');
    } catch (e) { setError(e.message); }
    finally { setBusy(false); }
  };

  return <div className="auth-shell">
    <div className="auth-art"><div className="auth-orbit"><SacredGeometry/></div><span className="eyebrow on-dark">{t('INDIAN KNOWLEDGE SYSTEMS',language)}</span><h1>IKSphere</h1><p>{t('Ancient knowledge, careful history, modern learning tools.',language)}</p><div className="auth-mini-grid"><span>{t('9 knowledge streams',language)}</span><span>{t('18+ deep lessons',language)}</span><span>{t('XP • badges • certificates',language)}</span><span>{t('Groq AI mentor',language)}</span></div></div>
    <div className="auth-panel">
      <div className="auth-brand"><img src="/iks_app_icon_1790916900784.jpg" alt="IKSphere"/><div><b>IKSphere</b><small>विद्या • विनय • विचार</small></div><select value={language} onChange={e=>setLanguage(e.target.value)} aria-label="Language"><option value="en">EN</option><option value="hi">हिंदी</option><option value="mr">मराठी</option></select></div>
      <h2>{t('welcome',language)} • {t('signIn',language)}</h2><div className="segmented auth-role-picker"><button className={accountType==='learner'?'active':''} onClick={()=>{setAccountType('learner');onRequestedRole('learner');if(mode==='guest')setMode('google')}}>{t('Student sign in',language)}</button><button className={accountType==='teacher'?'active':''} onClick={()=>{setAccountType('teacher');onRequestedRole('teacher');if(mode==='guest')setMode('google')}}>{t('Teacher sign in',language)}</button></div><p className="muted">{accountType==='teacher'?t('Teacher access requires your email to be listed in the server TEACHER_EMAILS setting.',language):t('Sign in as a learner to study IKS courses and join classes.',language)}</p>
      <div className="auth-tabs"><button className={mode==='google'?'active':''} onClick={()=>setMode('google')}><Users size={16}/> {t('Google',language)}</button><button className={mode==='email'?'active':''} onClick={()=>setMode('email')}><LogIn size={16}/> {t('email',language)}</button>{accountType==='learner'&&<button className={mode==='guest'?'active':''} onClick={()=>setMode('guest')}><UserRound size={16}/> {t('Guest',language)}</button>}</div>
      {mode==='google'&&<div className="auth-stack"><button className="google-btn" onClick={handleGoogle} disabled={busy||!firebaseConfigured}><span className="google-mark">G</span>{busy?t('Connecting…',language):t('google',language)}</button>{!firebaseConfigured&&<div className="config-warning"><SlidersHorizontal size={16}/><div><b>{t('Firebase is not configured yet.',language)}</b><span>{t('Add the VITE_FIREBASE_* values from your Firebase Web app to',language)} <code>frontend/.env.local</code>.</span></div></div>}{accountType==='learner'&&<button className="secondary wide" onClick={handleGuest} disabled={busy}><UserRound size={16}/>{t('guest',language)}</button>}</div>}
      {mode==='email'&&<div className="auth-stack">{create&&<label>{t('name',language)}<input value={name} onChange={e=>setName(e.target.value)} placeholder={t('Your name',language)} autoComplete="name"/></label>}<label>{t('email',language)}<input value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com" autoComplete="email" inputMode="email"/></label><label>{t('password',language)}<input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder={t('Minimum 6 characters',language)} autoComplete={create?'new-password':'current-password'}/></label><button className="primary wide" onClick={handleEmail} disabled={busy||!firebaseConfigured}>{busy?t('Working…',language):create?t('createAccount',language):t('signIn',language)}</button><button className="text-btn center" onClick={()=>setCreate(x=>!x)}>{create?t('Already have an account? Sign in',language):t('New to IKSphere? Create an account',language)}</button></div>}
      {mode==='guest'&&<div className="auth-stack"><label>{t('name',language)}<input value={name} onChange={e=>setName(e.target.value)} placeholder={t('Guest Learner',language)}/></label><button className="primary wide" onClick={handleGuest} disabled={busy}>{busy?t('Entering…',language):t('guest',language)}</button><div className="privacy-note"><ShieldCheck size={17}/><span>{t('Guest accounts keep progress on the app backend without asking for a password.',language)}</span></div></div>}
      {localOnly&&<div className="auth-stack"><button className="secondary wide" onClick={()=>handleLocalDemo(false)}>{t('Learner demo',language)}</button><button className="secondary wide" onClick={()=>handleLocalDemo(true)}>{t('Teacher demo',language)}</button></div>}
      <button className="text-btn center" onClick={()=>setLocalOnly(x=>!x)}>{localOnly?t('Hide',language):t('Show',language)} {t('local development access',language)}</button>
      {error&&<div className="form-error">{error}</div>}
      <div className="auth-foot"><span>{t('Mobile-first PWA',language)}</span><span>•</span><span>{t('Light / dark',language)}</span><span>•</span><span>{t('Groq-only AI',language)}</span></div>
    </div>
  </div>;
}

function Loader({label='Loading…'}) { return <div className="loader"><LoaderCircle className="spin"/><p>{label}</p></div>; }

function SacredGeometry({compact=false}) {
  const ref = useRef(null);
  useEffect(()=>{
    const canvas=ref.current;if(!canvas)return;const ctx=canvas.getContext('2d');let raf=0,t=0;
    const resize=()=>{const d=Math.min(2,window.devicePixelRatio||1);const r=canvas.getBoundingClientRect();canvas.width=Math.max(1,r.width*d);canvas.height=Math.max(1,r.height*d);ctx.setTransform(d,0,0,d,0,0)};
    const draw=()=>{t+=0.01;const r=canvas.getBoundingClientRect(),w=r.width,h=r.height,cx=w/2,cy=h/2,rad=Math.min(w,h)*0.35;ctx.clearRect(0,0,w,h);ctx.save();ctx.translate(cx,cy);ctx.rotate(Math.sin(t*.45)*.015);const glow=ctx.createRadialGradient(0,0,4,0,0,rad*1.15);glow.addColorStop(0,'rgba(255,193,74,.35)');glow.addColorStop(1,'rgba(199,93,12,0)');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(0,0,rad*1.2,0,Math.PI*2);ctx.fill();
      for(let i=0;i<24;i++){const a=(Math.PI*2*i/24)+t*.11;ctx.strokeStyle='rgba(255,190,64,.23)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(Math.cos(a)*rad*.82,Math.sin(a)*rad*.82);ctx.lineTo(Math.cos(a)*rad*1.15,Math.sin(a)*rad*1.15);ctx.stroke()}
      const triangle=(rot,scale)=>{ctx.beginPath();for(let i=0;i<3;i++){const a=rot+i*Math.PI*2/3;const x=Math.cos(a)*rad*scale,y=Math.sin(a)*rad*scale;i?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.closePath();ctx.stroke()};
      for(let i=0;i<9;i++){ctx.strokeStyle=`rgba(255,219,133,${.14+i*.02})`;triangle(Math.PI/2+(i%2?Math.PI:0),.22+i*.065)}
      for(let i=0;i<12;i++){ctx.strokeStyle='rgba(199,93,12,.22)';ctx.beginPath();const rr=rad*(.5+i*.035);ctx.arc(0,0,rr,0,Math.PI*2);ctx.stroke()}
      for(let i=0;i<8;i++){ctx.strokeStyle='rgba(255,197,73,.20)';ctx.beginPath();ctx.ellipse(0,0,rad*.7,rad*.28,i*Math.PI/8+t*.06,0,Math.PI*2);ctx.stroke()}
      ctx.fillStyle='#ffe5a2';ctx.beginPath();ctx.arc(0,0,4,0,Math.PI*2);ctx.fill();ctx.restore();raf=requestAnimationFrame(draw)};resize();window.addEventListener('resize',resize);draw();return()=>{cancelAnimationFrame(raf);window.removeEventListener('resize',resize)};
  },[]);
  return <canvas ref={ref} className={compact?'sacred-canvas compact':'sacred-canvas'} aria-label="Animated Sri Yantra inspired sacred geometry"/>;
}

function DailyWisdom({home, notify}) {
  const [playing,setPlaying]=useState(false),[copied,setCopied]=useState(false); const w=home?.wisdom;if(!w)return null;
  const text=`${w.sanskrit}\n\n${w.iast}\n\n${w.translation}\n\n${w.source}`;
  const copy=async()=>{try{await navigator.clipboard.writeText(text);setCopied(true);setTimeout(()=>setCopied(false),1500)}catch{notify(t('Clipboard access is unavailable on this device.'))}};
  const play=()=>{if(!('speechSynthesis' in window))return notify(t('Speech playback is not supported here'));window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(w.iast);u.lang='en-US';u.rate=.7;u.onstart=()=>setPlaying(true);u.onend=()=>setPlaying(false);u.onerror=()=>setPlaying(false);window.speechSynthesis.speak(u)};
  const share=async()=>{if(navigator.share){try{await navigator.share({title:'IKSphere Daily Wisdom',text})}catch{}}else{await copy();notify(t('Wisdom copied'))}};
  return <section className="wisdom panel glow-card"><div className="section-line"><div><span className="eyebrow">{t('dailyWisdom')}</span><h3>{w.source}</h3></div><div className="action-row"><button className={playing?'icon-btn live-btn':'icon-btn'} onClick={play} title={t('play')}><Volume2/></button><button className="icon-btn" onClick={copy} title={t('copy')}><Copy/></button><button className="icon-btn" onClick={share} title={t('share')}><Share2/></button></div></div><div className="soundwave">{Array.from({length:26},(_,i)=><span key={i} className={playing?'live':''} style={{'--i':i}}/>)}</div><div className="sanskrit-xl">{w.sanskrit.split('\n').map((line,i)=><div key={i}>{line}</div>)}</div><div className="iast">{w.iast}</div><p className="meaning">{w.translation}</p><div className="term-row">{(w.word_by_word||[]).slice(0,7).map(x=><span key={x}>{x}</span>)}</div><small className="muted">{copied?t('Copied.'):t('Read the script → check the IAST → understand the meaning.')}</small></section>
}

function Streak({streak}) { const arr=streak?.last7||[];return <div className="panel streak-panel"><div className="section-line"><div><span className="eyebrow">{t('streak')}</span><h3><Flame size={19}/> {streak?.current||0} {t('days')}</h3></div><span className="pill">{t('7-day view')}</span></div><div className="streak-grid">{arr.map((on,i)=><div key={i} className={on?'streak-cell on':'streak-cell'}><span>{['M','T','W','T','F','S','S'][i]}</span><i/></div>)}</div></div> }

function Dashboard({dashboard,home,courses,paths,scholar,quiz,setPage,open,notify}) {
  const firstIncomplete=courses.flatMap(c=>c.lessons.map(l=>({c,l}))).find(x=>!x.l.completed);
  return <div className="page-stack">
    <section className="hero panel"><div className="hero-image"><img src="/iks_hero_banner_1790916915515.jpg" alt="Indian knowledge heritage"/><div className="hero-geometry"><SacredGeometry/></div></div><div className="hero-copy"><span className="eyebrow">IKSPHERE • {new Date().toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long'})}</span><h1>{t('Learn the knowledge traditions of India.')}</h1><p>{t('Study mathematics, astronomy, health traditions, metallurgy, architecture, philosophy, linguistics, agriculture and water systems—with historical nuance.')}</p><div className="hero-actions"><button className="primary" onClick={()=>firstIncomplete?open('lesson',firstIncomplete.l.id):setPage('learn')}>{firstIncomplete?<><Play size={16}/>{t('continueLearning')}</>:<><BookOpen size={16}/>{t('learn')}</>}</button><button className="secondary" onClick={()=>setPage('explore')}><Search size={16}/>{t('explore')}</button></div><div className="hero-badges"><span><Sparkles size={14}/> {t('Mobile-first')}</span><span><ShieldCheck size={14}/> {t('Evidence-aware')}</span><span><Brain size={14}/> Groq AI</span></div></div></section>
    <div className="stats-grid mobile-stat-grid"><Stat icon={Flame} label={t('streak')} value={`${dashboard?.streak?.current||0}`} sub={t('days')}/><Stat icon={Trophy} label={t('xp')} value={dashboard?.stats?.xp||0} sub={dashboard?.stats?.rank?.name}/><Stat icon={BookmarkCheck} label={t('bookmarks')} value={dashboard?.stats?.bookmarks||0} sub={t('saved lessons')}/><Stat icon={CheckCircle2} label={t('Progress')} value={`${Math.round(dashboard?.stats?.completion_pct||0)}%`} sub={`${dashboard?.stats?.completed_lessons||0}/${dashboard?.stats?.total_lessons||0} ${t('lessons')}`}/></div>
    <DailyWisdom home={home} notify={notify}/>
    <div className="two-col"><Streak streak={dashboard?.streak}/><section className="panel scholar-card-home"><div className="section-line"><div><span className="eyebrow">{t('scholarOfDay')}</span><h3>{home?.scholar_of_day?.name}</h3></div><span className="pill">{home?.scholar_of_day?.era}</span></div><p>{home?.scholar_of_day?.contribution}</p><div className="meta-row"><span><MapPin/>{home?.scholar_of_day?.location}</span><span><BookOpen size={14}/>{home?.scholar_of_day?.work}</span></div><button className="text-btn" onClick={()=>setPage('scholars')}>{t('Open scholar timeline')} <ChevronRight size={15}/></button></section></div>
    <section className="panel daily-challenge"><div className="challenge-icon"><CircleHelp/></div><div><span className="eyebrow">{t('dailyChallenge')}</span><h3>{quiz?.title||t('Knowledge checkpoint')}</h3><p>{quiz?.description||t('One focused quiz to reinforce your learning.')}</p></div><button className="primary" onClick={()=>setPage('quiz')}>{t('Start')} <ArrowRight size={16}/></button></section>
    <section><SectionTitle eyebrow={t('FEATURED LEARNING')} title={t('Start with one stream')}/><div className="course-grid">{courses.slice(0,3).map(c=><CourseCard key={c.id} c={c} onClick={()=>open('course',c.id)}/>)}</div></section>
  </div>
}

function MapPin(){ return <span className="inline-icon">⌖</span> }
function SectionTitle({eyebrow,title,sub,action}){return <div className="section-head"><div><span className="eyebrow">{eyebrow}</span><h2>{title}</h2>{sub&&<p>{sub}</p>}</div>{action}</div>}
function Stat({icon:Icon,label,value,sub}){return <div className="stat"><div className="stat-icon"><Icon size={18}/></div><div><span>{label}</span><b>{value}</b><small>{sub}</small></div></div>}
function CourseCard({c,onClick}){return <button className="course-card" onClick={onClick}><div className="course-top"><span className="emoji">{c.icon}</span><span className="pill">{t(c.category)}</span></div><h3>{c.title}</h3><p>{c.description}</p><div className="course-meta"><span><BookOpen size={14}/>{c.lessons?.length||0} {t('lessons')}</span><span><Clock3 size={14}/>{c.duration}</span></div><div className="progress-line"><span style={{width:`${c.progress_pct||0}%`}}/></div><small>{Math.round(c.progress_pct||0)}% {t('complete')}</small></button>}

function Explore({courses,scholars,search,setSearch,open}) {
  const [cat,setCat]=useState('All');const q=search.trim().toLowerCase();
  const filtered=useMemo(()=>courses.filter(c=>(cat==='All'||c.category===cat||c.category.includes(cat))&&(!q||JSON.stringify(c).toLowerCase().includes(q))),[courses,cat,q]);
  const scholarMatches=q?scholars.filter(s=>JSON.stringify(s).toLowerCase().includes(q)):[];
  return <div className="page-stack"><SectionTitle eyebrow={t('Knowledge Hub')} title={t('Explore Indian knowledge')} sub={t('Search concepts, lessons, texts and scholars. Only IKS learning content is included in IKSphere.')}/><div className="search-large"><Search/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder={t('Try: zero, Aryabhata, Panini, Wootz, Kallanai…')}/></div><div className="chip-row">{CATS.map(x=><button key={x} className={cat===x?'filter-chip active':'filter-chip'} onClick={()=>setCat(x)}>{t(x)}</button>)}</div><div className="course-grid">{filtered.map(c=><CourseCard key={c.id} c={c} onClick={()=>open('course',c.id)}/>)}</div>{q&&scholarMatches.length>0&&<section className="panel"><SectionTitle eyebrow={t('SCHOLARS')} title={t('Matching scholars')}/><div className="mini-list">{scholarMatches.map(s=><button key={s.id} className="mini-row" onClick={()=>open('scholar',s.id)}><span className="avatar">{s.name[0]}</span><span><b>{s.name}</b><small>{s.domain} • {s.work}</small></span><ChevronRight/></button>)}</div></section>}{!filtered.length&&<EmptyState text={t('noResults')}/>}</div>
}

function Courses({courses,open}){return <div className="page-stack"><SectionTitle eyebrow={t('learn')} title={t('Deep-dive courses')} sub={t('Each lesson combines Sanskrit support, historical context, modern parallels and a checkpoint.')}/><div className="course-grid">{courses.map(c=><CourseCard key={c.id} c={c} onClick={()=>open('course',c.id)}/>)}</div></div>}

function CourseViewer({courseId,user,initialLessonId,close,refresh,notify}){
  const [course,setCourse]=useState(null),[lessonId,setLessonId]=useState(initialLessonId||null),[lesson,setLesson]=useState(null),[note,setNote]=useState(''),[checked,setChecked]=useState(false),[selectedAnswer,setSelectedAnswer]=useState(null),[busy,setBusy]=useState(false),[speaking,setSpeaking]=useState(false);
  useEffect(()=>{let alive=true;(async()=>{try{const c=await api.course(courseId,user.id);if(!alive)return;setCourse(c);setLessonId(initialLessonId||c.lessons[0]?.id||null)}catch(e){notify(e.message)}})();return()=>{alive=false}},[courseId,user.id]);
  useEffect(()=>{let alive=true;if(!lessonId)return; (async()=>{try{const l=await api.lesson(lessonId,user.id);if(alive){setLesson(l);setChecked(false);setSelectedAnswer(null)}}catch(e){notify(e.message)}})();return()=>{alive=false}},[lessonId,user.id]);
  if(!course||!lesson)return <div className="modal-backdrop"><div className="modal full"><Loader/></div></div>;
  const check=(idx)=>{setSelectedAnswer(idx);setChecked(idx===Number(lesson.checkpoint?.answer_index))};
  const saveNote=async()=>{if(!note.trim())return;setBusy(true);try{await api.createNote({lesson_id:lesson.id,content:note.trim()},user.id);setNote('');notify(t('Note saved'))}catch(e){notify(e.message)}finally{setBusy(false)}};
  const bookmark=async()=>{try{const r=await api.toggleBookmark(lesson.id,user.id);setLesson(l=>({...l,bookmarked:r.bookmarked}));refresh();notify(t(r.bookmarked?'Lesson bookmarked':'Bookmark removed'))}catch(e){notify(e.message)}};
  const pronounce=()=>{if(!('speechSynthesis' in window))return notify(t('Speech playback is not supported here'));window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(lesson.iast||lesson.sanskrit||lesson.title);u.lang='en-US';u.rate=.72;u.onstart=()=>setSpeaking(true);u.onend=()=>setSpeaking(false);u.onerror=()=>setSpeaking(false);window.speechSynthesis.speak(u)};
  const complete=async()=>{if(lesson.checkpoint?.question&&!lesson.completed&&!checked)return notify(t('Answer the knowledge checkpoint first'));setBusy(true);try{await api.progress(lesson.id,true,user.id);setLesson(l=>({...l,completed:true}));const c=await api.course(courseId,user.id);setCourse(c);refresh();notify(t('Lesson completed • +20 XP'))}catch(e){notify(e.message)}finally{setBusy(false)}};
  const current=course.lessons.findIndex(l=>l.id===lesson.id), next=current<course.lessons.length-1?course.lessons[current+1]:null;
  return <div className="modal-backdrop"><div className="modal full course-modal"><header className="course-modal-head"><button className="icon-btn" onClick={close}><ArrowLeft/></button><div><span className="eyebrow">{t(course.category)}</span><h2>{course.title}</h2></div><button className="icon-btn" onClick={close}><X/></button></header><div className="course-modal-grid"><aside className="lesson-list">{course.lessons.map((l,i)=><button key={l.id} className={l.id===lesson.id?'lesson-item active':'lesson-item'} onClick={()=>setLessonId(l.id)}><span>{l.completed?<Check size={12}/>:i+1}</span><div><b>{l.title}</b><small>{l.minutes} {t('minutes')} • {t(l.difficulty)}</small></div></button>)}</aside><article className="reader"><div className="reader-tools"><span className="pill">{t('Lesson')} {current+1} / {course.lessons.length}</span><div className="action-row"><button className={speaking?'icon-btn live-btn':'icon-btn'} onClick={pronounce} title={t('Play Sanskrit pronunciation')} aria-label={t('Play Sanskrit pronunciation')}><Volume2/></button><button className="icon-btn" onClick={bookmark} aria-label={t('Bookmark lesson')}>{lesson.bookmarked?<BookmarkCheck/>:<Bookmark/>}</button><button className="icon-btn" onClick={()=>navigator.clipboard?.writeText(`${lesson.title}\n${lesson.sanskrit}\n${lesson.iast}\n${lesson.english_meaning}`)} aria-label={t('Copy lesson')}><Copy/></button></div></div><h1>{lesson.title}</h1>{(course.texts||[]).length>0&&<div className="source-strip"><span className="eyebrow">{t('TEXTUAL SOURCES')}</span><div className="term-row">{course.texts.map(x=><span key={x}>{x}</span>)}</div></div>}{lesson.sanskrit&&<div className="sanskrit-block"><div>{lesson.sanskrit}</div><small>{lesson.meter}</small></div>}{lesson.iast&&<div className="iast-box"><b>IAST</b><span>{lesson.iast}</span></div>}<div className="meaning-box"><span>{t('Plain-language meaning')}</span><p>{lesson.english_meaning||lesson.overview}</p></div><div className="reader-grid"><div className="reader-section"><span className="eyebrow">{t('HISTORICAL CONTEXT')}</span><p>{lesson.historical_context||lesson.content}</p></div><div className="reader-section"><span className="eyebrow">{t('MODERN PARALLEL')}</span><p>{lesson.modern_parallel}</p></div></div>{lesson.source&&<div className="evidence-box"><span className="eyebrow">{t('SOURCE & EVIDENCE')}</span><p>{lesson.source}</p><small>{t('IKSphere distinguishes historical evidence, traditional interpretation and modern comparison.')}</small></div>}<div className="reader-section"><h3>{t('Key takeaways')}</h3><ul>{(lesson.takeaways||[]).map(x=><li key={x}>{x}</li>)}</ul></div><div className="callout"><Lightbulb size={18}/><div><b>{t('Real-world connection')}</b><p>{lesson.practical}</p></div></div>{(lesson.word_by_word||[]).length>0&&<div className="term-row">{lesson.word_by_word.map(x=><span key={x}>{x}</span>)}</div>}<div className="checkpoint"><div className="section-line"><div><span className="eyebrow">{t('KNOWLEDGE CHECKPOINT')}</span><h3>{lesson.checkpoint?.question||t('Reflect on the lesson: what is the central idea?')}</h3></div><CircleHelp/></div><div className="checkpoint-options">{(lesson.checkpoint?.options||[t('Review the lesson and identify its central idea')]).map((x,i)=><button key={x} className={`${selectedAnswer===i?'selected':''} ${checked&&i===Number(lesson.checkpoint.answer_index)?'correct':''} ${checked&&selectedAnswer===i&&i!==Number(lesson.checkpoint.answer_index)?'incorrect':''}`} onClick={()=>lesson.checkpoint?.options&&check(i)}>{String.fromCharCode(65+i)}<span>{x}</span></button>)}</div>{checked&&<div className="checkpoint-result"><CheckCircle2 size={16}/>{lesson.checkpoint.explanation}</div>}</div><div className="note-box"><span className="eyebrow">{t('PERSONAL NOTE')}</span><textarea value={note} onChange={e=>setNote(e.target.value)} placeholder={t('Write a study note…')}/><button className="secondary" onClick={saveNote} disabled={busy||!note.trim()}><Clipboard size={15}/>{t('saveNote')}</button></div><footer className="reader-footer"><button className="secondary" onClick={complete} disabled={busy||lesson.completed}>{lesson.completed?<><CheckCircle2 size={16}/>{t('completed')}</>:<><Check size={16}/>{t('markComplete')}</>}</button><button className="primary" onClick={()=>next&&setLessonId(next.id)} disabled={!next||(!lesson.completed&&!checked)}>{t('nextLesson')} <ArrowRight size={16}/></button></footer></article></div></div></div>
}

function Paths({paths,open}){return <div className="page-stack"><SectionTitle eyebrow={t('GUIDED PATHS')} title={t('Multi-week journeys')} sub={t('Sequential learning paths across the IKS streams.')}/><div className="path-grid">{paths.map(p=><button key={p.id} className="path-card" onClick={()=>open('path',p.id)}><div className="path-top"><span className="path-icon">🧭</span><span className="pill">{t(p.level)}</span></div><h3>{p.title}</h3><p>{p.courses.length} {t('courses')} • {p.weeks} {t('weeks')}</p><div className="progress-line"><span style={{width:`${p.progress_pct||0}%`}}/></div><small>{Math.round(p.progress_pct||0)}% {t('progress')}</small><div className="path-courses">{p.courses.slice(0,3).map(c=><span key={c.id}>{c.icon} {c.title}</span>)}</div></button>)}</div></div>}

function PathViewer({pathId,paths,close,open}){const p=paths.find(x=>x.id===pathId);if(!p)return null;return <div className="modal-backdrop"><div className="modal"><header className="modal-head"><div><span className="eyebrow">{t('GUIDED ROADMAP')}</span><h2>{p.title}</h2><p>{t(p.level)} • {p.weeks} {t('weeks')}</p></div><button className="icon-btn" onClick={close}><X/></button></header><div className="roadmap">{p.courses.map((c,i)=><button key={c.id} className="road-row" onClick={()=>{open('course',c.id);close()}}><span className="road-num">{i+1}</span><span><b>{c.title}</b><small>{c.lesson_count} {t('lessons')} • {Math.round(c.progress_pct||0)}% {t('complete')}</small></span><ChevronRight/></button>)}</div></div></div>}

function Classrooms({courses,quizzes,user,notify,openCourse,openQuiz}){
  const [classes,setClasses]=useState([]),[selected,setSelected]=useState(null),[assignments,setAssignments]=useState([]),[className,setClassName]=useState(''),[joinCode,setJoinCode]=useState(''),[contentId,setContentId]=useState(''),[contentType,setContentType]=useState('course'),[busy,setBusy]=useState(false);
  const teacher=user.role==='teacher';
  const load=async()=>{try{setClasses(await api.classrooms(user.id))}catch(e){notify(e.message)}};
  useEffect(()=>{load()},[user.id]);
  const create=async()=>{if(className.trim().length<2)return notify(t('Enter a class name with at least two characters.'));setBusy(true);try{const result=await api.createClassroom({name:className.trim()},user.id);setClasses(current=>[result,...current]);setSelected(result.id);setAssignments([]);setClassName('');notify(t('Class created. Share its join code with your students.'))}catch(e){notify(e.message)}finally{setBusy(false)}};
  const join=async()=>{if(!joinCode.trim())return notify(t('Enter the class join code.'));setBusy(true);try{const result=await api.joinClassroom(joinCode.trim(),user.id);setJoinCode('');await load();setSelected(result.id);notify(t('Joined classroom')+': '+result.name)}catch(e){notify(e.message)}finally{setBusy(false)}};
  const openClass=async(id)=>{setSelected(id);setBusy(true);try{setAssignments(await api.classroomAssignments(id,user.id))}catch(e){notify(e.message)}finally{setBusy(false)}};
  const assign=async()=>{if(!selected||!contentId)return notify(t('Choose course or quiz content first.'));setBusy(true);try{await api.assignClassroomContent(selected,{[contentType+'_id']:contentId},user.id);setAssignments(await api.classroomAssignments(selected,user.id));notify(t('Content assigned to class'))}catch(e){notify(e.message)}finally{setBusy(false)}};
  const selectedClass=classes.find(c=>c.id===selected);
  return <div className="page-stack"><SectionTitle eyebrow={teacher?t('TEACHER STUDIO') :t('STUDENT LEARNING')} title={teacher?t('Classrooms'):t('My classes')} sub={teacher?t('Create classes, share a join code, and assign IKS courses or quizzes.'):t('Join a teacher’s IKS class to see assigned courses and quizzes.')}/>
    {teacher?<section className="panel form-stack"><label>{t('New class name')}<input value={className} onChange={e=>setClassName(e.target.value)} placeholder={t('Ganita study group')}/></label><button className="primary" onClick={create} disabled={busy}><Plus size={16}/> {t('Create class')}</button></section>:<section className="panel form-stack"><label>{t('Join code')}<input value={joinCode} onChange={e=>setJoinCode(e.target.value.toUpperCase())} maxLength={20} placeholder={t('Enter your teacher’s code')}/></label><button className="primary" onClick={join} disabled={busy}>{t('Join class')}</button></section>}
    {classes.length>0&&<div className="classroom-grid">{classes.map(c=><button key={c.id} className={selected===c.id?'classroom-card selected':'classroom-card'} onClick={()=>openClass(c.id)}><span className="eyebrow">{teacher?`${c.student_count} students`:c.teacher_name}</span><h3>{c.name}</h3>{teacher&&<span className="join-code">JOIN CODE <b>{c.join_code}</b></span>}</button>)}</div>}
    {selectedClass&&<section className="panel form-stack"><SectionTitle eyebrow={t('CLASS CONTENT')} title={selectedClass.name}/>
      {teacher&&<div className="assignment-form"><select value={contentType} onChange={e=>{setContentType(e.target.value);setContentId('')}}><option value="course">{t('Course')}</option><option value="quiz">{t('Quiz')}</option></select><select value={contentId} onChange={e=>setContentId(e.target.value)}><option value="">{t('Select content…')}</option>{(contentType==='course'?courses:quizzes).map(item=><option key={item.id} value={item.id}>{item.title}</option>)}</select><button className="secondary" disabled={busy||!contentId} onClick={assign}>{t('Assign')}</button></div>}
      {assignments.length?<div className="assignment-list">{assignments.map(a=><button key={a.id} className="assignment-row" onClick={()=>a.course_id?openCourse(a.course_id):openQuiz(a.quiz_id)}><span className="pill">{a.course_id?t('COURSE'):t('QUIZ')}</span><b>{a.course_title||a.quiz_title}</b><ChevronRight size={16}/></button>)}</div>:<EmptyState text={t('No content assigned to this class yet.')}/>}
    </section>}
  </div>
}

function QuizHub({quizzes,user,notify,initialQuizId,onQuizStarted}){
  const [mode,setMode]=useState('quiz'),[active,setActive]=useState(null),[answers,setAnswers]=useState([]),[result,setResult]=useState(null),[cards,setCards]=useState([]),[cardIndex,setCardIndex]=useState(0),[flipped,setFlipped]=useState(false),[busy,setBusy]=useState(false);
  const start=async(id)=>{setBusy(true);try{setActive(await api.quiz(id,user.id));setAnswers([]);setResult(null);onQuizStarted?.()}catch(e){notify(e.message)}finally{setBusy(false)}};
  const submit=async()=>{if(!active||answers.length!==active.questions.length)return notify(`${t('Answer all')} ${active?.questions.length||0} ${t('questions')}.`);setBusy(true);try{setResult(await api.attempt(active.id,answers,user.id))}catch(e){notify(e.message)}finally{setBusy(false)}};
  const loadCards=async()=>{setBusy(true);try{const result=await api.flashcardReview(user.id);setCards(result.cards)}catch(e){notify(e.message)}finally{setBusy(false)}};
  const reviewCard=async(cardId,rating)=>{setBusy(true);try{const result=await api.reviewFlashcard(cardId,rating,user.id);setCards(current=>current.map(card=>card.id===cardId?{...card,due:0,repetitions:result.repetitions,interval_days:result.interval_days,due_at:result.due_at,last_reviewed_at:new Date().toISOString()}:card));setCardIndex(0);setFlipped(false);const wait=result.interval_days<1?t('10 minutes'):result.interval_days+' '+(result.interval_days===1?t('day'):t('days'));notify(t('Review saved. Next review in')+' '+wait)}catch(e){notify(e.message)}finally{setBusy(false)}};
  useEffect(()=>{loadCards()},[user.id]);
  useEffect(()=>{if(initialQuizId)start(initialQuizId)},[initialQuizId]);
  if(result)return <div className="page-stack"><SectionTitle eyebrow={t('QUIZ RESULT')} title={`${result.percent}% • ${result.score}/${result.total}`} action={<button className="secondary" onClick={()=>setResult(null)}><RotateCcw size={15}/> {t('Retry later')}</button>}/><div className="result-list">{result.review.map((r,i)=><div className={r.correct?'review ok':'review bad'} key={r.question_id}><span>{r.correct?<Check/>:<X/>}</span><div><b>{t('Question')} {i+1}. {r.question}</b><p>{t('Correct:')} {r.correct_answer}</p><small>{r.explanation}</small></div></div>)}</div></div>;
  if(active)return <div className="page-stack"><button className="back-link" onClick={()=>setActive(null)}><ArrowLeft size={15}/> {t('All quizzes')}</button><section className="panel quiz-panel"><div className="section-line"><div><span className="eyebrow">{t('Quiz')}</span><h2>{active.title}</h2><p>{active.description}</p></div><span className="pill">{answers.length}/{active.questions.length}</span></div>{active.questions.map((q,i)=><div className="quiz-question" key={q.id}><b>{i+1}. {q.question}</b><div className="quiz-options">{q.options.map((o,j)=><button className={answers[i]===j?'selected':''} key={o} onClick={()=>setAnswers(a=>{const x=[...a];x[i]=j;return x})}>{String.fromCharCode(65+j)}<span>{o}</span></button>)}</div></div>)}<button className="primary wide" onClick={submit} disabled={busy}>{busy?t('Checking…'):t('Submit quiz')}<CheckCircle2 size={16}/></button></section></div>;
  return <div className="page-stack"><SectionTitle eyebrow={t('QUIZ & MEMORY')} title={t('Quiz center + flashcards')} sub={t('Practice retrieval, review explanations, then flip through concepts.')}/><div className="segmented"><button className={mode==='quiz'?'active':''} onClick={()=>setMode('quiz')}><CircleHelp size={15}/> {t('Quizzes')}</button><button className={mode==='cards'?'active':''} onClick={()=>setMode('cards')}><LayersIcon/> {t('Flashcards')}</button></div>{mode==='quiz'?<div className="quiz-grid">{quizzes.map(q=><button key={q.id} className="quiz-card" onClick={()=>start(q.id)}><div className="course-top"><span className="emoji">🧠</span><span className="pill">{q.question_count} {t('questions')}</span></div><h3>{q.title}</h3><p>{q.description}</p>{q.last_percent!=null&&<small>{t('Last attempt:')} {Math.round(q.last_percent)}%</small>}</button>)}</div>:<FlashcardLab cards={cards} index={cardIndex} setIndex={setCardIndex} flipped={flipped} setFlipped={setFlipped} onReview={reviewCard} busy={busy}/>}</div>
}
function LayersIcon(){return <span className="layers-icon">◇</span>}
function FlashcardLab({cards,index,setIndex,flipped,setFlipped,onReview,busy}){
  const [dueOnly,setDueOnly]=useState(true),dueCards=cards.filter(card=>card.due),visible=dueOnly?dueCards:cards;
  const move=d=>{setFlipped(false);setIndex((index+d+visible.length)%visible.length)};
  const selectQueue=value=>{setDueOnly(value);setIndex(0);setFlipped(false)};
  if(!cards.length)return <EmptyState text={t('No flashcards available.')}/>;
  if(!visible.length)return <section className="panel review-empty"><span className="eyebrow">{t('Review complete')}</span><h3>{t("You're all caught up.")}</h3><p>{t('Your next scheduled cards will appear here when they are due.')}</p><button className="secondary" onClick={()=>selectQueue(false)}>{t('Browse all')} {cards.length} {t('cards')}</button></section>;
  const c=visible[index%visible.length];
  return <div className="flash-lab">
    <div className="review-queue segmented"><button className={dueOnly?'active':''} onClick={()=>selectQueue(true)}>{t('Due today')} <span>{dueCards.length}</span></button><button className={!dueOnly?'active':''} onClick={()=>selectQueue(false)}>{t('All cards')} <span>{cards.length}</span></button></div>
    <div className="flash-meta"><span className="pill">{c.category}</span><b>{t('Card')} {index%visible.length+1} / {visible.length}</b><button className="secondary" onClick={()=>{setFlipped(false);setIndex(Math.floor(Math.random()*visible.length))}}>{t('Shuffle')}</button></div>
    <button className={flipped?'flashcard flipped':'flashcard'} onClick={()=>setFlipped(x=>!x)}><div className="flash-inner"><div className="flash-face front"><span className="eyebrow">{t('CONCEPT')}</span><h2>{c.front}</h2><small>{t('Try to recall the answer, then tap to reveal it.')}</small></div><div className="flash-face back"><span className="eyebrow">{t('BREAKDOWN')}</span><h3>{c.back}</h3><div className="parallel"><b>{t('Modern parallel')}</b><p>{c.parallel}</p></div></div></div></button>
    <div className="flash-review-status"><span className={c.due?'review-due':'review-scheduled'}>{c.due?t('Due for review'):`${t('Next review in')} ${c.interval_days<1?t('10 minutes'):`${c.interval_days} ${c.interval_days===1?t('day'):t('days')}`}`}</span>{c.repetitions>0&&<small>{t('Successful reviews:')} {c.repetitions}</small>}</div>
    {flipped&&<div className="review-ratings" aria-label={t('How well did you recall this card?')}><span>{t('How well did you recall this card?')}</span><div><button className="rating-again" disabled={busy} onClick={()=>onReview(c.id,'again')}>{t('Again')}</button><button className="rating-hard" disabled={busy} onClick={()=>onReview(c.id,'hard')}>{t('Hard')}</button><button className="rating-good" disabled={busy} onClick={()=>onReview(c.id,'good')}>{t('Good')}</button><button className="rating-easy" disabled={busy} onClick={()=>onReview(c.id,'easy')}>{t('Easy')}</button></div></div>}
    <div className="flash-nav"><button className="icon-btn" onClick={()=>move(-1)} disabled={visible.length<2}><ArrowLeft/></button><button className="icon-btn" onClick={()=>move(1)} disabled={visible.length<2}><ArrowRight/></button></div>
  </div>
}

function Analytics({analytics,dashboard}){const data=analytics?.by_category||[];const max=Math.max(1,...data.map(x=>x.total||0));return <div className="page-stack"><SectionTitle eyebrow={t('ANALYTICS')} title={t('Your learning map')} sub={t('See completion and study distribution by knowledge stream.')}/><div className="stats-grid"><Stat icon={Trophy} label={t('XP')} value={analytics?.xp||0} sub={analytics?.rank?.name}/><Stat icon={Flame} label={t('Streak')} value={`${analytics?.streak?.current||0}`} sub={t('days')}/><Stat icon={CircleHelp} label={t('Best quiz')} value={`${Math.round(analytics?.quiz?.best||0)}%`} sub={`${analytics?.quiz?.attempts||0} ${t('attempts')}`}/><Stat icon={CheckCircle2} label={t('Overall')} value={`${Math.round(dashboard?.stats?.completion_pct||0)}%`} sub={t('lesson completion')}/></div><section className="panel bars"><SectionTitle eyebrow={t('BY STREAM')} title={t('Study distribution')}/>{data.map(d=><div className="bar-row" key={d.category}><div><span>{t(d.category)}</span><b>{d.completed||0}/{d.total||0}</b></div><div className="bar-bg"><span style={{width:`${Math.max(3,(d.total||0)/max*100)}%`}}/></div></div>)}</section></div>}

function Achievements({achievements}){return <div className="page-stack"><SectionTitle eyebrow={t('ACHIEVEMENTS')} title={`${achievements.rank.name} • ${achievements.xp} XP`} sub={t('Ranks move from Jijnasu to Acharya as you learn and practice.')}/><section className="rank-hero panel"><div className="rank-symbol">✦</div><div><span className="pill">{achievements.rank.subtitle}</span><h2>{achievements.rank.name}</h2><p>Jijnasu → Vidyarthi → Upadhyaya → Acharya</p></div></section><SectionTitle eyebrow={t('BADGES')} title={t('Achievement collection')}/><div className="badge-grid">{achievements.badges.map(b=><div className={b.awarded_at?'badge-card earned':'badge-card'} key={b.id}><div className="badge-icon">{b.icon}</div><div><b>{b.name}</b><p>{b.description}</p><small>{b.condition_text}</small></div></div>)}</div><SectionTitle eyebrow={t('CERTIFICATES')} title={t('Learning certificates')}/><div className="cert-list">{achievements.certificates.map(c=><div className="cert-row" key={c.id}><span className="cert-seal">✺</span><div><b>{c.title}</b><small>{c.certificate_no} • {c.issued_at.slice(0,10)}</small></div><CertificateDownload cert={c}/></div>)}</div>{!achievements.certificates.length&&<EmptyState text={t('Complete a whole course to unlock a certificate.')}/>}</div>}
function CertificateDownload({cert}){const [busy,setBusy]=useState(false);const download=async()=>{setBusy(true);try{const user=JSON.parse(localStorage.getItem('iksphere_user')||'null');const blob=await api.certificateBlob(cert.id,user.id);const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`${cert.certificate_no}.pdf`;a.click();URL.revokeObjectURL(url)}catch(e){alert(e.message)}finally{setBusy(false)}};return <button className="secondary" onClick={download} disabled={busy}>{busy?<LoaderCircle className="spin" size={14}/>:<Download size={14}/>} PDF</button>}

function Mentor({user,notify,language}){
  const welcomeMessage=t('mentorWelcome',language),welcomeRef=useRef(welcomeMessage);
  const [messages,setMessages]=useState([{role:'assistant',content:welcomeMessage}]);
  const [input,setInput]=useState('');const [busy,setBusy]=useState(false);
  useEffect(()=>{setMessages(current=>current.length===1&&current[0].role==='assistant'&&current[0].content===welcomeRef.current?[{...current[0],content:welcomeMessage}]:current);welcomeRef.current=welcomeMessage},[welcomeMessage]);
  useEffect(()=>{api.aiHistory(user.id).then(h=>{if(h?.length)setMessages(h.map(x=>({role:x.role,content:x.content}))) }).catch(()=>{})},[user.id]);
  const ask=async(text=input)=>{if(!text.trim()||busy)return;setInput('');const next=[...messages,{role:'user',content:text.trim()}];setMessages(next);setBusy(true);try{const languageName={en:'English',hi:'Hindi',mr:'Marathi'}[language]||'English';const r=await api.ask(text,`The user is inside the IKSphere mobile learning app. Reply in ${languageName} unless the user asks for another language. Explain Sanskrit terms briefly when useful.`,user.id,next);setMessages(m=>[...m,{role:'assistant',content:r.answer,meta:r.offline?'Offline curated engine':r.model}]);}catch(e){notify(e.message)}finally{setBusy(false)}};
  const suggestions=['Explain śūnya and place value','Help me read this Sanskrit word: gaṇita','How is Aryabhata\'s Earth-rotation model described?','What is the difference between history and modern science?'];
  const clear=async()=>{try{await api.clearAiHistory(user.id);setMessages([{role:'assistant',content:t('mentorCleared',language)}])}catch(e){notify(e.message)}};
  return <div className="page-stack"><SectionTitle eyebrow={t('SAMVADA')} title={t('AI Guru Mentor')} sub={`${t('Groq-powered when configured')} • ${language.toUpperCase()} ${t('interface')}`} action={<button className="secondary" onClick={clear}><Trash2 size={14}/> {t('clear')}</button>}/><div className="mentor panel"><div className="suggestion-row">{suggestions.map(s=><button key={s} onClick={()=>ask(s)}>{t(s)}</button>)}</div><div className="chat-history">{messages.map((m,i)=><div className={m.role==='assistant'?'chat-msg ai':'chat-msg user'} key={i}><div className="chat-avatar">{m.role==='assistant'?<Brain size={15}/>:<UserRound size={15}/>}</div><div className="chat-bubble"><div>{m.content.split('\n').map((x,j)=><p key={j}>{x||' '}</p>)}</div>{m.meta&&<small>{m.meta}</small>}</div></div>)}{busy&&<div className="chat-msg ai"><div className="chat-avatar"><Brain size={15}/></div><div className="typing">{t('Samvāda is thinking…')} <span/><span/><span/></div></div>}</div><div className="chat-composer"><textarea value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();ask()}}} placeholder={t('Ask anything…')} rows="1"/><button className="primary icon-submit" onClick={()=>ask()} disabled={!input.trim()||busy}><Send size={17}/></button></div></div></div>}

function Notes({notes,bookmarks,open,refresh,notify,user}){return <div className="page-stack"><SectionTitle eyebrow={t('LIBRARY')} title={t('Notes & bookmarks')} sub={t('Keep your study trail linked to lessons.')}/><div className="two-col"><section className="panel"><SectionTitle eyebrow={t('BOOKMARKS')} title={`${bookmarks.length} ${t('saved')}`}/>{bookmarks.map(b=><button key={b.lesson_id} className="mini-row" onClick={()=>open('lesson',b.lesson_id)}><BookmarkCheck size={16}/><span><b>{b.title}</b><small>{b.course_title}</small></span><ChevronRight/></button>)}{!bookmarks.length&&<EmptyState text={t('Bookmark a lesson to see it here.')}/>}</section><section className="panel"><SectionTitle eyebrow={t('NOTES')} title={`${notes.length} ${t('notes')}`}/>{notes.map(n=><div className="note-row" key={n.id}><div><b>{n.lesson_title}</b><small>{n.course_title} • {n.updated_at.slice(0,10)}</small><p>{n.content}</p></div><button className="icon-btn" onClick={async()=>{try{await api.deleteNote(n.id,user.id);refresh();notify(t('Note deleted'))}catch(e){notify(e.message)}}}><Trash2/></button></div>)}{!notes.length&&<EmptyState text={t('Your first lesson note will appear here.')}/>}</section></div></div>}

function Timeline({scholars,open}){return <div className="page-stack"><SectionTitle eyebrow={t('SCHOLARS')} title={t('Historical timeline')} sub={t('Profiles are presented as study objects; quotations are labeled as textual anchors where attribution is uncertain.')}/><div className="timeline">{scholars.map(s=><button className="timeline-card" key={s.id} onClick={()=>open('scholar',s.id)}><div className="timeline-dot"/><div className="timeline-head"><span className="avatar xl">{s.name[0]}</span><div><span className="pill">{s.era}</span><h3>{s.name} <span>{s.sanskrit}</span></h3><p>{t(s.domain)}</p></div></div><div className="timeline-grid"><div><span>{t('Work')}</span><b>{s.work}</b></div><div><span>{t('Location')}</span><b>{s.location}</b></div><div className="wide"><span>{t('Contribution')}</span><p>{s.contribution}</p></div></div></button>)}</div></div>}

function ScholarModal({scholar,close}){if(!scholar)return null;return <div className="modal-backdrop"><div className="modal"><header className="modal-head"><div><span className="eyebrow">{t('SCHOLAR PROFILE')}</span><h2>{scholar.name}</h2><p>{scholar.sanskrit} • {scholar.era}</p></div><button className="icon-btn" onClick={close}><X/></button></header><div className="profile-hero"><div className="avatar xl">{scholar.name[0]}</div><div><b>{t(scholar.domain)}</b><p>{scholar.contribution}</p></div></div><div className="detail-grid"><div><span>{t('Seminal work')}</span><b>{scholar.work}</b></div><div><span>{t('Location')}</span><b>{scholar.location}</b></div><div className="wide"><span>{t('Textual anchor')}</span><b>{scholar.quote}</b><small>{scholar.quote_note}</small></div></div><button className="secondary wide" onClick={()=>navigator.clipboard?.writeText(`${scholar.name} — ${scholar.work}\n${scholar.contribution}`)}><Copy size={15}/> {t('Copy profile')}</button></div></div>}

function AchievementsPage({achievements}){return <Achievements achievements={achievements}/>}

function SanskritGuide(){const [data,setData]=useState(null);useEffect(()=>{api.sanskritGuide().then(setData).catch(()=>{})},[]);return <div className="page-stack"><SectionTitle eyebrow={t('LANGUAGE HELP')} title={t('Sanskrit reading guide')} sub={t('A small pronunciation aid for learners who do not read Devanagari yet.')}/><section className="panel guide-intro"><div className="sanskrit-demo">अ आ इ ई उ ऊ ऋ ए ऐ ओ औ</div><div><b>{t('IAST makes sound differences visible.')}</b><p>{t('ā = long a • ī = long i • ū = long u • ṛ = vocalic r • ś / ṣ = different “sh” sounds • ṃ = nasal marker • ḥ = visarga.')}</p></div></section>{data&&<><section><SectionTitle eyebrow={t('VOWELS')} title={t('स्वर • vowels')}/><GuideGrid items={data.vowels}/></section><section><SectionTitle eyebrow={t('CONSONANTS')} title={t('व्यञ्जन • consonants')}/><GuideGrid items={data.consonants}/></section><section><SectionTitle eyebrow={t('COMMON TERMS')} title={t('Words you will see in IKSphere')}/><GuideGrid items={data.terms}/></section></>}</div>}
function GuideGrid({items=[]}){return <div className="guide-grid">{items.map(([script,latin,meaning])=><div className="guide-card" key={script+latin}><b>{script}</b><span>{latin}</span><small>{t(meaning)}</small></div>)}</div>}

function Teacher({courses,user,refresh,notify}){
  const [tab,setTab]=useState('course');const [title,setTitle]=useState('');const [category,setCategory]=useState(CATS[1]);const [editingCourseId,setEditingCourseId]=useState('');const [editingCourse,setEditingCourse]=useState(null);const [lessons,setLessons]=useState([{title:'',sanskrit:'',iast:'',overview:'',content:'',english_meaning:'',historical_context:'',modern_parallel:'',source:'',takeaways:[],word_by_word:[],practical:'',minutes:15,difficulty:'Beginner',checkpoint:{question:'',options:['','','',''],answer_index:0,explanation:''}}]);
  const [quizTitle,setQuizTitle]=useState('');const [quizCourse,setQuizCourse]=useState(courses[0]?.id||'');const [questions,setQuestions]=useState([{question:'',options:['','','',''],answer_index:0,explanation:''}]);
  const [pathTitle,setPathTitle]=useState('');const [pathWeeks,setPathWeeks]=useState(4);const [pathCourses,setPathCourses]=useState([]);const [busy,setBusy]=useState(false);
  const loadCourse=async(id)=>{setEditingCourseId(id);if(!id){setEditingCourse(null);setTitle('');setCategory(CATS[1]);setLessons([{title:'',sanskrit:'',iast:'',overview:'',content:'',english_meaning:'',historical_context:'',modern_parallel:'',source:'',takeaways:[],word_by_word:[],practical:'',minutes:15,difficulty:'Beginner',checkpoint:{question:'',options:['','','',''],answer_index:0,explanation:''}}]);return}setBusy(true);try{const course=await api.course(id,user.id);setEditingCourse(course);setTitle(course.title);setCategory(course.category);setLessons(course.lessons.map(({completed,bookmarked,position,...lesson})=>lesson))}catch(e){notify(e.message)}finally{setBusy(false)}};
  const saveCourse=async()=>{if(!title.trim()||lessons.some(l=>!l.title.trim()||!l.content.trim()))return notify('Add a course title and complete each lesson title/content.');setBusy(true);try{const payload={...(editingCourse||{}),title,category,sanskrit:editingCourse?.sanskrit||'',icon:editingCourse?.icon||'📚',level:editingCourse?.level||'Beginner',duration:editingCourse?.duration||`${Math.max(1,Math.ceil(lessons.length/2))} weeks`,description:editingCourse?.description||'Teacher-authored IKS learning course.',era:editingCourse?.era||'Historical study',highlights:editingCourse?.highlights||[],texts:editingCourse?.texts||[],lessons};if(editingCourseId)await api.updateCourse(editingCourseId,payload,user.id);else await api.createCourse(payload,user.id);await refresh();notify(editingCourseId?'Course updated':'Course published');await loadCourse(editingCourseId)}catch(e){notify(e.message)}finally{setBusy(false)}};
  const saveQuiz=async()=>{if(!quizTitle.trim()||questions.some(q=>!q.question.trim()||q.options.some(o=>!o.trim())))return notify('Complete the quiz title and all options.');setBusy(true);try{await api.createQuiz({course_id:quizCourse,title:quizTitle,description:'Teacher-authored IKS checkpoint',questions},user.id);await refresh();setQuizTitle('');notify('Quiz published')}catch(e){notify(e.message)}finally{setBusy(false)}};
  const savePath=async()=>{if(!pathTitle.trim()||!pathCourses.length)return notify('Add a title and select at least one course.');setBusy(true);try{await api.createPath({title:pathTitle,weeks:Number(pathWeeks),level:'Beginner',course_ids:pathCourses},user.id);await refresh();setPathTitle('');setPathCourses([]);notify('Learning path published')}catch(e){notify(e.message)}finally{setBusy(false)}};
  const addLesson=()=>setLessons(l=>[...l,{title:'',sanskrit:'',iast:'',overview:'',content:'',english_meaning:'',historical_context:'',modern_parallel:'',source:'',takeaways:[],word_by_word:[],practical:'',minutes:15,difficulty:'Beginner',checkpoint:{question:'',options:['','','',''],answer_index:0,explanation:''}}]);
  const updateLesson=(i,k,v)=>setLessons(a=>a.map((l,j)=>j===i?{...l,[k]:v?.target?.value ?? v}:l));
  return <div className="page-stack"><SectionTitle eyebrow={t('TEACHER')} title={t('Teacher Studio')} sub={t('Author IKS-only courses, checkpoints and learning paths.')}/><div className="segmented"><button className={tab==='course'?'active':''} onClick={()=>setTab('course')}>{t('Course')}</button><button className={tab==='quiz'?'active':''} onClick={()=>setTab('quiz')}>{t('Quiz')}</button><button className={tab==='path'?'active':''} onClick={()=>setTab('path')}>{t('Path')}</button></div>{tab==='course'&&<section className="panel form-stack"><label>{t('Edit existing course')}<select value={editingCourseId} onChange={e=>loadCourse(e.target.value)}><option value="">{t('Create a new course…')}</option>{courses.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select></label><label>{t('Course title')}<input value={title} onChange={e=>setTitle(e.target.value)} placeholder={t('Indian Astronomy Foundations')}/></label><label>{t('Knowledge stream')}<select value={category} onChange={e=>setCategory(e.target.value)}>{CATS.slice(1).map(c=><option key={c}>{t(c)}</option>)}</select></label>{lessons.map((l,i)=><div className="builder-card" key={i}><div className="builder-number">{i+1}</div><div className="builder-fields"><input value={l.title} onChange={e=>updateLesson(i,'title',e)} placeholder={t('Lesson title')}/><div className="two-input"><input value={l.sanskrit} onChange={e=>updateLesson(i,'sanskrit',e)} placeholder={t('Devanagari / Sanskrit')}/><input value={l.iast} onChange={e=>updateLesson(i,'iast',e)} placeholder="IAST"/></div><textarea value={l.content} onChange={e=>updateLesson(i,'content',e)} placeholder={t('Lesson content')}/><textarea value={l.historical_context} onChange={e=>updateLesson(i,'historical_context',e)} placeholder={t('Historical context')}/><textarea value={l.modern_parallel} onChange={e=>updateLesson(i,'modern_parallel',e)} placeholder={t('Modern parallel (clearly labeled)')}/><textarea value={l.practical} onChange={e=>updateLesson(i,'practical',e)} placeholder={t('Real-world learning application')}/><input value={l.word_by_word.join(', ')} onChange={e=>updateLesson(i,'word_by_word',e.target.value.split(',').map(x=>x.trim()).filter(Boolean))} placeholder={t('Sanskrit help / key terms, comma separated')}/><textarea value={l.checkpoint.question} onChange={e=>updateLesson(i,'checkpoint',{...l.checkpoint,question:e.target.value})} placeholder={t('Checkpoint question')}/><div className="option-builder">{l.checkpoint.options.map((o,j)=><input key={j} value={o} onChange={e=>updateLesson(i,'checkpoint',{...l.checkpoint,options:l.checkpoint.options.map((v,k)=>k===j?e.target.value:v)})} placeholder={`${t('Option')} ${String.fromCharCode(65+j)}`}/>)}</div></div></div>)}<button className="secondary" onClick={addLesson}><Plus size={15}/> {t('Add lesson')}</button><button className="primary wide" onClick={saveCourse} disabled={busy}>{busy?t('Saving…'):editingCourseId?t('Save course changes'):t('Publish course')}<GraduationCap size={16}/></button></section>}{tab==='quiz'&&<section className="panel form-stack"><label>{t('Quiz title')}<input value={quizTitle} onChange={e=>setQuizTitle(e.target.value)} placeholder={t('Astronomy checkpoint')}/></label><label>{t('Course')}<select value={quizCourse} onChange={e=>setQuizCourse(e.target.value)}>{courses.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select></label>{questions.map((q,i)=><div className="builder-card" key={i}><div className="builder-number">{i+1}</div><div className="builder-fields"><input value={q.question} onChange={e=>setQuestions(a=>a.map((x,j)=>j===i?{...x,question:e.target.value}:x))} placeholder={t('Question')}/><div className="option-builder">{q.options.map((o,j)=><input key={j} value={o} onChange={e=>setQuestions(a=>a.map((x,k)=>k===i?{...x,options:x.options.map((v,m)=>m===j?e.target.value:v)}:x))} placeholder={`${t('Option')} ${String.fromCharCode(65+j)}`}/>)}</div><select value={q.answer_index} onChange={e=>setQuestions(a=>a.map((x,j)=>j===i?{...x,answer_index:Number(e.target.value)}:x))}><option value="0">{t('Correct A')}</option><option value="1">{t('Correct B')}</option><option value="2">{t('Correct C')}</option><option value="3">{t('Correct D')}</option></select><textarea value={q.explanation} onChange={e=>setQuestions(a=>a.map((x,j)=>j===i?{...x,explanation:e.target.value}:x))} placeholder={t('Explanation')}/></div></div>)}<button className="secondary" onClick={()=>setQuestions(a=>[...a,{question:'',options:['','','',''],answer_index:0,explanation:''}])}><Plus size={15}/> {t('Add question')}</button><button className="primary wide" onClick={saveQuiz} disabled={busy}>{busy?t('Publishing…'):t('Publish quiz')}</button></section>}{tab==='path'&&<section className="panel form-stack"><label>{t('Path title')}<input value={pathTitle} onChange={e=>setPathTitle(e.target.value)} placeholder={t('Vedic Mathematics Journey')}/></label><label>{t('Weeks')}<input type="number" value={pathWeeks} min="1" max="52" onChange={e=>setPathWeeks(Math.max(1,Math.min(52,Number(e.target.value)||1)))}/></label><div className="select-courses">{courses.map(c=><button key={c.id} className={pathCourses.includes(c.id)?'selected':''} onClick={()=>setPathCourses(a=>a.includes(c.id)?a.filter(x=>x!==c.id):[...a,c.id])}><span>{c.icon}</span><b>{c.title}</b><small>{c.lessons.length} {t('lessons')}</small></button>)}</div><button className="primary wide" onClick={savePath} disabled={busy}>{busy?t('Publishing…'):t('Publish learning path')}<Waypoints size={16}/></button></section>}</div>;
}

function SettingsPage({theme,setTheme,accent,setAccent,language,setLanguage,user,setUser,notify,config,onOpenGuide}){
  const [reduced,setReduced]=usePersistedState('iksphere_reduce_motion','0');
  const install=async()=>{const p=window.__iksInstallPrompt;if(p){await p.prompt();window.__iksInstallPrompt=null}else notify('Use your browser menu → Install app / Add to Home Screen.')};
  const clear=()=>{if(confirm('Clear local appearance preferences?')){localStorage.removeItem('iksphere_accent');localStorage.removeItem('iksphere_reduce_motion');location.reload()}};
  const logout=async()=>{try{await firebaseLogout()}catch{} clearApiSession();localStorage.removeItem('iksphere_user');setUser(null)};
  return <div className="page-stack"><SectionTitle eyebrow={t('settings',language)} title={t('settingsTitle',language)} sub={t('Theme, language, mobile behavior and connection status.')}/><div className="settings-grid"><section className="panel"><SectionTitle eyebrow={t('theme',language)} title={t('Appearance',language)}/><div className="theme-buttons"><button className={theme==='light'?'active':''} onClick={()=>setTheme('light')}><Sun size={16}/> {t('light',language)}</button><button className={theme==='dark'?'active':''} onClick={()=>setTheme('dark')}><Moon size={16}/> {t('dark',language)}</button></div><label>{t('language',language)}<select value={language} onChange={e=>setLanguage(e.target.value)}><option value="en">English</option><option value="hi">हिन्दी</option><option value="mr">मराठी</option></select></label><label>{t('accent',language)}<input type="color" value={accent} onChange={e=>setAccent(e.target.value)}/></label><div className="swatches">{['#c75d0c','#ffb300','#5c4bdb','#0b7d77','#c83e6f'].map(c=><button key={c} style={{background:c}} onClick={()=>setAccent(c)} aria-label={`Accent ${c}`}/>)}</div><label className="toggle-row"><span><b>{t('reduceMotion',language)}</b><small>{t('Reduce decorative motion',language)}</small></span><input type="checkbox" checked={reduced==='1'||reduced===true} onChange={e=>{const v=e.target.checked?'1':'0';setReduced(v);document.documentElement.dataset.reduceMotion=v}}/></label><button className="secondary wide" onClick={install}><Download size={15}/> {t('Install IKSphere on this device',language)}</button><button className="secondary wide" onClick={clear}>{t('Reset local appearance',language)}</button></section><section className="panel"><SectionTitle eyebrow={t('ACCOUNT',language)} title={user.name}/><div className="profile-hero"><span className="avatar xl">{user.name[0]}</span><div><b>{user.email||t('Guest account',language)}</b><p>{user.provider} • {t(user.role,language)}</p></div></div><div className="status-stack"><Status ok={firebaseConfigured} label={t('Firebase Web authentication',language)} detail={firebaseConfigured?t('Configured in this build',language):t('Add VITE_FIREBASE_* keys for Google/email + anonymous Firebase auth',language)}/><Status ok={!!config?.groq_configured} label={t('Groq AI',language)} detail={config?.groq_configured?`Server model: ${config.groq_model||'configured'}`:'Add GROQ_API_KEY to backend/.env'}/><Status ok={!!config?.supabase_configured} label={t('Learning database',language)} detail={config?.supabase_configured?'Supabase PostgreSQL':t('Local SQLite fallback',language)}/></div><div className="privacy-note"><ShieldCheck size={17}/><span>No Kotlin or Android runtime. The app is React/Vite PWA + Node.js/Express + Python/FastAPI.</span></div><button className="danger-btn wide" onClick={logout}>{t('Sign out',language)}</button></section></div><section className="panel"><SectionTitle eyebrow={t('LANGUAGE HELP',language)} title={t('Sanskrit reading guide',language)} sub={t('Open pronunciation support for Devanagari and IAST.',language)} action={<button className="secondary" onClick={onOpenGuide}>{t('Open guide',language)} <ChevronRight size={15}/></button>}/></section></div>
}
function Status({ok=true,label,detail}){return <div className="status-row"><span className={ok?'status-dot ok':'status-dot'}/><div><b>{label}</b><small>{detail}</small></div></div>}

function EmptyState({text}){return <div className="empty"><MoreHorizontal size={22}/><p>{text}</p></div>}

function AppShell({user,setUser}){
  const [page,setPage]=useState('home'),[selected,setSelected]=useState(null),[quizLaunchId,setQuizLaunchId]=useState(null),[theme,setTheme]=usePersistedState('iksphere_theme','light'),[accent,setAccent]=usePersistedState('iksphere_accent','#c75d0c'),[language,setLanguage]=usePersistedState('iksphere_language',getLanguage()),[search,setSearch]=useState(''),[toast,setToast]=useState(''),[mobileMenu,setMobileMenu]=useState(false),[loading,setLoading]=useState(true);
  const [dashboard,setDashboard]=useState(null),[home,setHome]=useState(null),[courses,setCourses]=useState([]),[paths,setPaths]=useState([]),[quizzes,setQuizzes]=useState([]),[scholars,setScholars]=useState([]),[achievements,setAchievements]=useState(null),[analytics,setAnalytics]=useState(null),[bookmarks,setBookmarks]=useState([]),[notes,setNotes]=useState([]),[config,setConfig]=useState(null);
  const notify=(m)=>{setToast(m);clearTimeout(window.__iksToast);window.__iksToast=setTimeout(()=>setToast(''),2800)};
  const refresh=async()=>{setLoading(true);try{const [d,h,c,p,q,s,a,an,b,n,cfg]=await Promise.all([api.dashboard(user.id),api.home(user.id),api.courses(user.id),api.paths(user.id),api.quizzes(user.id),api.scholars(),api.achievements(user.id),api.analytics(user.id),api.bookmarks(user.id),api.notes(user.id),api.config()]);setDashboard(d);setHome(h);setCourses(c);setPaths(p);setQuizzes(q);setScholars(s);setAchievements(a);setAnalytics(an);setBookmarks(b);setNotes(n);setConfig(cfg)}catch(e){notify(e.message)}finally{setLoading(false)}};
  useEffect(()=>{refresh()},[user.id]);
  useEffect(()=>{document.documentElement.dataset.theme=theme;document.documentElement.style.setProperty('--accent',accent);document.documentElement.style.colorScheme=theme;document.documentElement.lang=language;document.documentElement.dataset.reduceMotion=localStorage.getItem('iksphere_reduce_motion')==='1'?'1':'0'},[theme,accent,language]);
  useEffect(()=>{localStorage.setItem('iksphere_user',JSON.stringify(user))},[user]);

  const menu=[['home',t('home',language),Home],['explore',t('explore',language),Search],['learn',t('learn',language),BookOpen],['paths',t('paths',language),Waypoints],['quiz',t('quiz',language),CircleHelp],['classes',t('classes',language),Users],['mentor',t('mentor',language),Brain],['library',t('library',language),BookmarkCheck],['scholars',t('scholars',language),Users],['achievements',t('achievements',language),Trophy],['sanskrit',t('sanskritGuide',language),Languages],...(user.role==='teacher'?[['teacher',t('teacher',language),GraduationCap]]:[]),['settings',t('settings',language),Settings]];
  const nav=id=>{setPage(id);setSelected(null);setMobileMenu(false)};const open=(kind,id)=>setSelected({kind,id});
  const content=useMemo(()=>({home:<Dashboard dashboard={dashboard} home={home} courses={courses} paths={paths} scholar={home?.scholar_of_day} quiz={home?.daily_quiz} setPage={nav} open={open} notify={notify}/>,explore:<Explore courses={courses} scholars={scholars} search={search} setSearch={setSearch} open={open}/>,learn:<Courses courses={courses} open={open}/>,paths:<Paths paths={paths} open={open}/>,quiz:<QuizHub quizzes={quizzes} user={user} notify={notify} initialQuizId={quizLaunchId} onQuizStarted={()=>setQuizLaunchId(null)}/>,classes:<Classrooms courses={courses} quizzes={quizzes} user={user} notify={notify} openCourse={id=>open('course',id)} openQuiz={id=>{setQuizLaunchId(id);nav('quiz')}}/>,mentor:<Mentor user={user} notify={notify} language={language}/>,library:<Notes notes={notes} bookmarks={bookmarks} open={open} refresh={refresh} notify={notify} user={user}/>,scholars:<Timeline scholars={scholars} open={open}/>,achievements:<AchievementsPage achievements={achievements||{rank:{name:'Jijnasu',subtitle:'Seeker'},xp:0,badges:[],certificates:[]}}/>,sanskrit:<SanskritGuide/>,teacher:<Teacher courses={courses} user={user} refresh={refresh} notify={notify}/>,settings:<SettingsPage theme={theme} setTheme={setTheme} accent={accent} setAccent={setAccent} language={language} setLanguage={setLanguage} user={user} setUser={setUser} notify={notify} config={config} onOpenGuide={()=>nav('sanskrit')}/>}),[page,dashboard,home,courses,paths,quizzes,scholars,achievements,analytics,bookmarks,notes,search,language,theme,accent,user,config,quizLaunchId]);

  const bottom=[['home',Home],['explore',Search],['learn',BookOpen],['quiz',CircleHelp],['mentor',Brain]];
  return <div className="app"><aside className={mobileMenu?'sidebar open':'sidebar'}><div className="brand"><img src="/iks_app_icon_1790916900784.jpg" alt="IKSphere"/><div><strong>IKSphere</strong><small>भारतीय ज्ञान परम्परा</small></div><button className="icon-btn mobile-only" onClick={()=>setMobileMenu(false)}><X/></button></div><nav>{menu.map(([id,label,Icon])=><button key={id} className={page===id?'nav-item active':'nav-item'} onClick={()=>nav(id)}><Icon size={18}/><span>{label}</span></button>)}</nav><div className="sidebar-user"><div className="mini-user"><span className="avatar">{user.name[0]}</span><div><b>{user.name}</b><small>{user.role}</small></div></div><button className="text-btn" onClick={()=>nav('settings')}>Account settings</button></div></aside><main><header className="topbar"><button className="icon-btn mobile-only" onClick={()=>setMobileMenu(true)}><Menu/></button><div className="crumb"><b>IKSphere</b><ChevronRight size={14}/><span>{menu.find(x=>x[0]===page)?.[1]}</span></div><div className="top-actions"><div className="top-search"><Search size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} onKeyDown={e=>e.key==='Enter'&&nav('explore')} placeholder={t('search',language)}/></div><button className="icon-btn" onClick={()=>setTheme(x=>x==='dark'?'light':'dark')} title="Theme">{theme==='dark'?<Sun/>:<Moon/>}</button><button className="avatar top-avatar" onClick={()=>nav('settings')}>{user.name[0]}</button></div></header><div className="content">{loading?<Loader/>:content[page]}</div></main><nav className="bottom-nav">{bottom.map(([id,Icon])=><button key={id} className={page===id?'active':''} onClick={()=>nav(id)}><Icon size={19}/><span>{menu.find(x=>x[0]===id)?.[1]}</span></button>)}<button onClick={()=>nav('settings')}><Settings size={19}/><span>{t('settings',language)}</span></button></nav>{toast&&<div className="toast"><CheckCircle2 size={16}/>{toast}</div>}
    {selected?.kind==='course'&&<CourseViewer courseId={selected.id} user={user} close={()=>setSelected(null)} refresh={refresh} notify={notify}/>} 
    {selected?.kind==='lesson'&&<CourseViewer courseId={courses.find(c=>c.lessons.some(l=>l.id===selected.id))?.id} user={user} initialLessonId={selected.id} close={()=>setSelected(null)} refresh={refresh} notify={notify}/>} 
    {selected?.kind==='path'&&<PathViewer pathId={selected.id} paths={paths} close={()=>setSelected(null)} open={open}/>} 
    {selected?.kind==='scholar'&&<ScholarModal scholar={scholars.find(s=>s.id===selected.id)} close={()=>setSelected(null)}/>} 
  </div>
}

function AppRouter(){
  const [user,setUser]=useState(null);const [authReady,setAuthReady]=useState(!firebaseConfigured);const [language,setLanguage]=usePersistedState('iksphere_language',getLanguage());const requestedRole=useRef('learner');
  useEffect(()=>{
    if(!firebaseConfigured){const saved=JSON.parse(localStorage.getItem('iksphere_user')||'null');if(saved)setUser(saved);return()=>{}};
    return observeFirebaseAuth(async(fUser)=>{
      if(!fUser){setAuthReady(true);return;}
      try{const token=await fUser.getIdToken();const apiUser=await api.authFirebase({id_token:token,name:fUser.displayName||'IKSphere Learner',email:fUser.email||'',provider:fUser.isAnonymous?'anonymous':(fUser.providerData[0]?.providerId||'firebase')});if(requestedRole.current==='teacher'&&apiUser.role!=='teacher')return;setApiSession({token,userId:apiUser.id});setUser(apiUser)}catch(err){console.error(err)}finally{setAuthReady(true)}});
  },[]);
  if(!authReady)return <Loader label="Connecting authentication…"/>;
  if(!user)return <LoginScreen onLogged={u=>setUser(u)} language={language} setLanguage={setLanguage} onRequestedRole={role=>{requestedRole.current=role}}/>;
  return <AppShell user={user} setUser={setUser}/>;
}

window.addEventListener('beforeinstallprompt',(e)=>{e.preventDefault();window.__iksInstallPrompt=e});
createRoot(document.getElementById('root')).render(<React.StrictMode><AppRouter/></React.StrictMode>);
